    moving={}
    for y in range(63):
        for x in range(63):
            if any(x0<=x<=x1 and y0<=y<=y1 for x0,y0,x1,y1 in boxes) and b[y][x] in (0,4,5):
                moving[x,y]=b[y][x]
    target=[(x,y) for y in range(63) for x in range(63) if b[y][x]==11]
    target_box=_bbox(target) if target else None
    for x,y in moving: b[y][x]=9
    for (x,y),c in moving.items():
        nx,ny=x+dx,y+dy
        if 0<=nx<64 and 0<=ny<64: b[ny][nx]=c
    moves=state["moves"]+1
    for y in range(min(moves,63)): b[y][63]=5
    won=False
    for c in (4,5):
        cells=[(x,y) for y in range(63) for x in range(63) if b[y][x]==c]
